StructuredText.Text:
#tempOpen := 0;
#tempClosed := 0;
#tempTransit := 0;
#tempFault := 0;
#tempLocal := 0;
#tempConfigured := 0;
#tempErOpen := 0;    #tempErClosed := 0;    #tempErTransit := 0;    #tempErFault := 0;    #tempErLocal := 0;    #tempErConfigured := 0;
#tempFwdOpen := 0;   #tempFwdClosed := 0;   #tempFwdTransit := 0;   #tempFwdFault := 0;   #tempFwdLocal := 0;   #tempFwdConfigured := 0;
#tempAftOpen := 0;   #tempAftClosed := 0;   #tempAftTransit := 0;   #tempAftFault := 0;   #tempAftLocal := 0;   #tempAftConfigured := 0;

// 1Hz Flashing Clock Generator (Toggles every ~500ms)
"Valves_DB".ClockCounter := "Valves_DB".ClockCounter + 1;
IF "Valves_DB".ClockCounter >= 10 THEN
    "Valves_DB".Clock_1Hz := NOT "Valves_DB".Clock_1Hz;
    "Valves_DB".ClockCounter := 0;
END_IF;

// Auto-initialize hardware health to TRUE (healthy until told otherwise) if all are FALSE at startup
IF NOT "Valves_DB".HwHealthy[1] AND NOT "Valves_DB".HwHealthy[8] THEN
    FOR #b := 1 TO 9 DO
        "Valves_DB".HwHealthy[#b] := TRUE;
    END_FOR;
END_IF;

FOR #i := 1 TO 88 DO
    IF "Valves_DB".Valve[#i].Configured THEN
        // Snapshot BEFORE this scan's command/timer processing runs — needed by the
        // Unexpected Movement (F) guard below to tell a genuine idle-and-unexplained drop
        // apart from a normal command-triggered one (a fresh command sets SimStep 0->nonzero
        // in section 1; a completing travel sets it nonzero->0 in section 2 — comparing
        // only the post-scan value can't distinguish either from true idle-the-whole-scan).
        #simStepAtStart := #SimStep[#i];

        // Auto-initialize Healthy status to TRUE and Resting Position to CLOSED seat — but
        // ONLY the first scan a valve is ever seen, via the Initialized latch. Simulation-only
        // scaffolding (see the Initialized member's comment in Valves_DB): without this
        // one-time gate, this ran every scan and silently reset ClosedFB back to TRUE any time
        // a valve was idle with both feedbacks false — which is exactly the state Loss of
        // Position (E) needs to sustain for 2s to fire, so E could never actually trigger.
        IF NOT "Valves_DB".Initialized[#i] THEN
            "Valves_DB".Initialized[#i] := TRUE;
            IF NOT "Valves_DB".Valve[#i].OpenFB AND NOT "Valves_DB".Valve[#i].ClosedFB AND #SimStep[#i] = 0 THEN
                "Valves_DB".Valve[#i].Healthy := TRUE;
                "Valves_DB".Valve[#i].ClosedFB := TRUE;
            END_IF;
        END_IF;

        // 1. Failsafe Command and Motion Simulation
        IF NOT "Valves_DB".Valve[#i].LocalMode AND "Valves_DB".Valve[#i].Healthy THEN
            // Interlock: Ignore if both commands pressed simultaneously
            IF "Valves_DB".Valve[#i].OpenCmd AND "Valves_DB".Valve[#i].CloseCmd THEN
                "Valves_DB".Valve[#i].OpenCmd := FALSE;
                "Valves_DB".Valve[#i].CloseCmd := FALSE;
            ELSIF "Valves_DB".Valve[#i].OpenCmd THEN
                // Start OPENING sequence: Immediately leave seat -> MOVING!
                "Valves_DB".Valve[#i].OpenFB := FALSE;
                "Valves_DB".Valve[#i].ClosedFB := FALSE;
                #SimStep[#i] := 1; // 1 = opening in progress
                "Valves_DB".Valve[#i].OpenCmd := FALSE;
                "Valves_DB".Valve[#i].CloseCmd := FALSE;
            ELSIF "Valves_DB".Valve[#i].CloseCmd THEN
                // Start CLOSING sequence: Immediately leave seat -> MOVING!
                "Valves_DB".Valve[#i].OpenFB := FALSE;
                "Valves_DB".Valve[#i].ClosedFB := FALSE;
                #SimStep[#i] := 2; // 2 = closing in progress
                "Valves_DB".Valve[#i].CloseCmd := FALSE;
                "Valves_DB".Valve[#i].OpenCmd := FALSE;
            END_IF;
        END_IF;

        // 2. Motion Delay Execution — real 3.0s TON per valve (Valve[i].TimerOpen/Close
        // are dedicated instances since they live inside this array element). Scan-cycle
        // counting was used before; it only equalled 3.0s if every scan took exactly
        // 100ms, which isn't guaranteed, so the MOVING state could flash by in well
        // under a second on a fast scan. A TON runs on the CPU's real-time clock, so
        // this duration is exact regardless of scan speed.
        // Stuck (set via the popup's SIMULATE STUCK toggle) holds the valve at the normal
        // 3s completion so it never arrives — TON.ET keeps counting past PT as long as IN
        // stays true, so at 8s (well past the normal 3s travel) that's a genuine failure to
        // arrive, not just "still moving": latch Fail to Open/Close (C/D) and give up on the
        // sequence, leaving both feedbacks false (position genuinely unknown).
        "Valves_DB".Valve[#i].TimerOpen(IN := #SimStep[#i] = 1, PT := T#8S);
        IF #SimStep[#i] = 1 THEN
            IF NOT "Valves_DB".Stuck[#i] AND "Valves_DB".Valve[#i].TimerOpen.ET >= T#3S THEN
                "Valves_DB".Valve[#i].OpenFB := TRUE;   // Reached OPEN position!
                "Valves_DB".Valve[#i].ClosedFB := FALSE;
                #SimStep[#i] := 0;                       // Sequence complete
            ELSIF "Valves_DB".Valve[#i].TimerOpen.Q THEN
                "Valves_DB".TimeoutOpenAlarm[#i] := TRUE;  // Fail to Open (C)
                "Valves_DB".Valve[#i].OpenFB := FALSE;
                "Valves_DB".Valve[#i].ClosedFB := FALSE;
                #SimStep[#i] := 0;
            END_IF;
        END_IF;

        "Valves_DB".Valve[#i].TimerClose(IN := #SimStep[#i] = 2, PT := T#8S);
        IF #SimStep[#i] = 2 THEN
            IF NOT "Valves_DB".Stuck[#i] AND "Valves_DB".Valve[#i].TimerClose.ET >= T#3S THEN
                "Valves_DB".Valve[#i].ClosedFB := TRUE; // Reached CLOSED position!
                "Valves_DB".Valve[#i].OpenFB := FALSE;
                #SimStep[#i] := 0;                       // Sequence complete
            ELSIF "Valves_DB".Valve[#i].TimerClose.Q THEN
                "Valves_DB".TimeoutCloseAlarm[#i] := TRUE; // Fail to Close (D)
                "Valves_DB".Valve[#i].OpenFB := FALSE;
                "Valves_DB".Valve[#i].ClosedFB := FALSE;
                #SimStep[#i] := 0;
            END_IF;
        END_IF;

        // 3. Failsafe Double Indication Fault Check
        IF "Valves_DB".Valve[#i].OpenFB AND "Valves_DB".Valve[#i].ClosedFB THEN
            "Valves_DB".Valve[#i].Healthy := FALSE; // Trip Fault
        END_IF;

        // 3a. Alarm conditions E (Loss of Position) and F (Unexpected Movement) — both
        // derived from the exact same OpenFB/ClosedFB pair used everywhere else; the only
        // extra ingredient is TIME and CONTEXT (was a command active, what did it say a
        // moment ago), not any new signal.
        //
        // E: idle (SimStep=0, so no travel is legitimately in progress) with NEITHER limit
        // switch made — held for 2s via PosLostTmr so a normal in-flight transition can't
        // false-trip it. Suppressed while a timeout (C/D) is already latched, since that is
        // the exact same physical symptom (no position) already alarmed under its own name.
        "Valves_DB".PosLostTmr[#i](
            IN := (#SimStep[#i] = 0) AND NOT "Valves_DB".Valve[#i].OpenFB
                  AND NOT "Valves_DB".Valve[#i].ClosedFB
                  AND NOT "Valves_DB".TimeoutOpenAlarm[#i] AND NOT "Valves_DB".TimeoutCloseAlarm[#i],
            PT := T#2S);

        // F: a limit switch that WAS made a scan ago has dropped, with no travel sequence
        // running to explain it — nobody commanded this, so something moved the valve
        // (handwheel) or a switch/wiring fault occurred. Latched.
        // Requires SimStep to have been 0 BOTH before and after this scan's processing: a
        // fresh command (0 -> nonzero, in section 1) or a completing travel (nonzero -> 0,
        // in section 2) each only satisfy ONE side of this, so both are correctly excluded —
        // only a scan truly idle throughout can reach here.
        IF #simStepAtStart = 0 AND #SimStep[#i] = 0 THEN
            IF ("Valves_DB".PrevOpenFB[#i] AND NOT "Valves_DB".Valve[#i].OpenFB) OR
               ("Valves_DB".PrevClosedFB[#i] AND NOT "Valves_DB".Valve[#i].ClosedFB) THEN
                "Valves_DB".UnexpMove[#i] := TRUE;
            END_IF;
        END_IF;
        "Valves_DB".PrevOpenFB[#i] := "Valves_DB".Valve[#i].OpenFB;
        "Valves_DB".PrevClosedFB[#i] := "Valves_DB".Valve[#i].ClosedFB;

        // 4. Priority Summary Counting — plant-wide AND per-zone in the same pass
        // (this loop already runs 1..88 every scan regardless, so the zone-scoped
        // increments below are free — they're what let every HMI KPI/caption cell
        // read one tag instead of re-looping its zone's 28-32 valves itself).
        // Zone valve-number ranges follow physical position from stern to bow, so the HMI
        // mimic reads CM-01..CM-88 straight across: AFT=1-28, ER=29-56, FWD=57-88.
        #tempConfigured := #tempConfigured + 1;
        IF #i <= 28 THEN
            #tempAftConfigured := #tempAftConfigured + 1;
        ELSIF #i <= 56 THEN
            #tempErConfigured := #tempErConfigured + 1;
        ELSE
            #tempFwdConfigured := #tempFwdConfigured + 1;
        END_IF;

        // StateCode is assigned in these same branches (0=UNCONFIGURED 1=FAULT 2=LOCAL
        // 3=OPEN 4=CLOSED 5=MOVING) so the HMI reads one Int per valve instead of
        // recombining five raw bits in JavaScript on every refresh.
        // UnexpMove (F) and PosLostTmr.Q (E) added here so a valve with a genuine position
        // problem shows FAULT instead of falling through to the default MOVING bucket below,
        // which was otherwise indistinguishable from a normal in-flight transition - the exact
        // blind spot E was designed to close, but the display logic was never updated to match.
        IF NOT "Valves_DB".Valve[#i].Healthy OR ("Valves_DB".Valve[#i].OpenFB AND "Valves_DB".Valve[#i].ClosedFB)
           OR "Valves_DB".TimeoutOpenAlarm[#i] OR "Valves_DB".TimeoutCloseAlarm[#i]
           OR "Valves_DB".UnexpMove[#i] OR "Valves_DB".PosLostTmr[#i].Q THEN
            "Valves_DB".StateCode[#i] := 1;
            #tempFault := #tempFault + 1;
            IF #i <= 28 THEN #tempAftFault := #tempAftFault + 1;
            ELSIF #i <= 56 THEN #tempErFault := #tempErFault + 1;
            ELSE #tempFwdFault := #tempFwdFault + 1;
            END_IF;
        ELSIF "Valves_DB".Valve[#i].LocalMode THEN
            "Valves_DB".StateCode[#i] := 2;
            #tempLocal := #tempLocal + 1;
            IF #i <= 28 THEN #tempAftLocal := #tempAftLocal + 1;
            ELSIF #i <= 56 THEN #tempErLocal := #tempErLocal + 1;
            ELSE #tempFwdLocal := #tempFwdLocal + 1;
            END_IF;
        ELSIF "Valves_DB".Valve[#i].OpenFB AND NOT "Valves_DB".Valve[#i].ClosedFB THEN
            "Valves_DB".StateCode[#i] := 3;
            #tempOpen := #tempOpen + 1;
            IF #i <= 28 THEN #tempAftOpen := #tempAftOpen + 1;
            ELSIF #i <= 56 THEN #tempErOpen := #tempErOpen + 1;
            ELSE #tempFwdOpen := #tempFwdOpen + 1;
            END_IF;
        ELSIF NOT "Valves_DB".Valve[#i].OpenFB AND "Valves_DB".Valve[#i].ClosedFB THEN
            "Valves_DB".StateCode[#i] := 4;
            #tempClosed := #tempClosed + 1;
            IF #i <= 28 THEN #tempAftClosed := #tempAftClosed + 1;
            ELSIF #i <= 56 THEN #tempErClosed := #tempErClosed + 1;
            ELSE #tempFwdClosed := #tempFwdClosed + 1;
            END_IF;
        ELSE
            "Valves_DB".StateCode[#i] := 5;
            #tempTransit := #tempTransit + 1; // MOVING state!
            IF #i <= 28 THEN #tempAftTransit := #tempAftTransit + 1;
            ELSIF #i <= 56 THEN #tempErTransit := #tempErTransit + 1;
            ELSE #tempFwdTransit := #tempFwdTransit + 1;
            END_IF;
        END_IF;
    ELSE
        "Valves_DB".StateCode[#i] := 0;
        "Valves_DB".Valve[#i].OpenCmd := FALSE;
        "Valves_DB".Valve[#i].CloseCmd := FALSE;
        // Don't let an unconfigured/removed valve leave a stale latched alarm behind.
        "Valves_DB".TimeoutOpenAlarm[#i] := FALSE;
        "Valves_DB".TimeoutCloseAlarm[#i] := FALSE;
        "Valves_DB".UnexpMove[#i] := FALSE;
        "Valves_DB".PrevOpenFB[#i] := FALSE;
        "Valves_DB".PrevClosedFB[#i] := FALSE;
    END_IF;
END_FOR;

"Valves_DB".TotalOpen := #tempOpen;
"Valves_DB".TotalClosed := #tempClosed;
"Valves_DB".TotalTransit := #tempTransit;
"Valves_DB".TotalFault := #tempFault;
"Valves_DB".TotalLocal := #tempLocal;
"Valves_DB".TotalConfigured := #tempConfigured;

"Valves_DB".ErOpen := #tempErOpen;
"Valves_DB".ErClosed := #tempErClosed;
"Valves_DB".ErTransit := #tempErTransit;
"Valves_DB".ErFault := #tempErFault;
"Valves_DB".ErLocal := #tempErLocal;
"Valves_DB".ErConfigured := #tempErConfigured;

"Valves_DB".FwdOpen := #tempFwdOpen;
"Valves_DB".FwdClosed := #tempFwdClosed;
"Valves_DB".FwdTransit := #tempFwdTransit;
"Valves_DB".FwdFault := #tempFwdFault;
"Valves_DB".FwdLocal := #tempFwdLocal;
"Valves_DB".FwdConfigured := #tempFwdConfigured;

"Valves_DB".AftOpen := #tempAftOpen;
"Valves_DB".AftClosed := #tempAftClosed;
"Valves_DB".AftTransit := #tempAftTransit;
"Valves_DB".AftFault := #tempAftFault;
"Valves_DB".AftLocal := #tempAftLocal;
"Valves_DB".AftConfigured := #tempAftConfigured;

// ---- Alarm condition bit-packing -----------------------------------------
// WinCC discrete alarms trigger off a bit within a Word tag (RaisedStateTag +
// RaisedStateTagBitNumber), not a bare Bool array element, so each of the 7 per-valve
// conditions gets packed into 6 words (96 bits, 88 used) here. Valve V's bit for any
// condition is word (V-1)/16, bit (V-1) MOD 16 — matches how the HMI-side alarm creation
// computes the same trigger address, so the two have to stay in lockstep.
FOR #w := 0 TO 5 DO
    #packWord := 0;
    FOR #b := 0 TO 15 DO
        #bitIdx := #w * 16 + #b + 1;
        IF #bitIdx <= 88 THEN
            IF "Valves_DB".Valve[#bitIdx].Configured AND NOT "Valves_DB".Valve[#bitIdx].Healthy THEN
                #packWord := #packWord OR SHL(IN := W#16#1, N := INT_TO_UDINT(#b));
            END_IF;
        END_IF;
    END_FOR;
    "Valves_DB".W_Unhealthy[#w] := #packWord;
END_FOR;

FOR #w := 0 TO 5 DO
    #packWord := 0;
    FOR #b := 0 TO 15 DO
        #bitIdx := #w * 16 + #b + 1;
        IF #bitIdx <= 88 THEN
            IF "Valves_DB".Valve[#bitIdx].Configured AND "Valves_DB".Valve[#bitIdx].OpenFB AND "Valves_DB".Valve[#bitIdx].ClosedFB THEN
                #packWord := #packWord OR SHL(IN := W#16#1, N := INT_TO_UDINT(#b));
            END_IF;
        END_IF;
    END_FOR;
    "Valves_DB".W_Conflict[#w] := #packWord;
END_FOR;

FOR #w := 0 TO 5 DO
    #packWord := 0;
    FOR #b := 0 TO 15 DO
        #bitIdx := #w * 16 + #b + 1;
        IF #bitIdx <= 88 THEN
            IF "Valves_DB".Valve[#bitIdx].Configured AND "Valves_DB".TimeoutOpenAlarm[#bitIdx] THEN
                #packWord := #packWord OR SHL(IN := W#16#1, N := INT_TO_UDINT(#b));
            END_IF;
        END_IF;
    END_FOR;
    "Valves_DB".W_FailOpen[#w] := #packWord;
END_FOR;

FOR #w := 0 TO 5 DO
    #packWord := 0;
    FOR #b := 0 TO 15 DO
        #bitIdx := #w * 16 + #b + 1;
        IF #bitIdx <= 88 THEN
            IF "Valves_DB".Valve[#bitIdx].Configured AND "Valves_DB".TimeoutCloseAlarm[#bitIdx] THEN
                #packWord := #packWord OR SHL(IN := W#16#1, N := INT_TO_UDINT(#b));
            END_IF;
        END_IF;
    END_FOR;
    "Valves_DB".W_FailClose[#w] := #packWord;
END_FOR;

FOR #w := 0 TO 5 DO
    #packWord := 0;
    FOR #b := 0 TO 15 DO
        #bitIdx := #w * 16 + #b + 1;
        IF #bitIdx <= 88 THEN
            IF "Valves_DB".Valve[#bitIdx].Configured AND "Valves_DB".PosLostTmr[#bitIdx].Q THEN
                #packWord := #packWord OR SHL(IN := W#16#1, N := INT_TO_UDINT(#b));
            END_IF;
        END_IF;
    END_FOR;
    "Valves_DB".W_LossPos[#w] := #packWord;
END_FOR;

FOR #w := 0 TO 5 DO
    #packWord := 0;
    FOR #b := 0 TO 15 DO
        #bitIdx := #w * 16 + #b + 1;
        IF #bitIdx <= 88 THEN
            IF "Valves_DB".Valve[#bitIdx].Configured AND "Valves_DB".UnexpMove[#bitIdx] THEN
                #packWord := #packWord OR SHL(IN := W#16#1, N := INT_TO_UDINT(#b));
            END_IF;
        END_IF;
    END_FOR;
    "Valves_DB".W_UnexpMove[#w] := #packWord;
END_FOR;

FOR #w := 0 TO 5 DO
    #packWord := 0;
    FOR #b := 0 TO 15 DO
        #bitIdx := #w * 16 + #b + 1;
        IF #bitIdx <= 88 THEN
            IF "Valves_DB".Valve[#bitIdx].Configured AND "Valves_DB".Valve[#bitIdx].LocalMode THEN
                #packWord := #packWord OR SHL(IN := W#16#1, N := INT_TO_UDINT(#b));
            END_IF;
        END_IF;
    END_FOR;
    "Valves_DB".W_Local[#w] := #packWord;
END_FOR;

// Simulated hardware health (indices 1..9) into a single word.
#packWord := 0;
FOR #b := 0 TO 8 DO
    IF NOT "Valves_DB".HwHealthy[#b + 1] THEN
        #packWord := #packWord OR SHL(IN := W#16#1, N := INT_TO_UDINT(#b));
    END_IF;
END_FOR;
"Valves_DB".HwWord := #packWord;

// ---- Paged table windows ------------------------------------------------
// The HMI valve table has 14 fixed slots. Copy whichever page each zone is showing into
// these windows so every HMI slot can bind to a constant tag name (e.g. ErTblState[3])
// rather than building the name in JavaScript from a page tag — that indirection is what
// forced the table onto ~126 polled scripts and made the screen slow to load.
// TblState = -1 marks a slot with no valve on this page (0 already means UNCONFIGURED).
// 14 iterations x 3 zones per scan is negligible next to the 88-valve loop above.

// AFT BALLAST: valves 1..28 (2 pages)
#base := 1 + "Valves_DB".AftPage * 14;
FOR #j := 1 TO 14 DO
    #idx := #base + #j - 1;
    IF #idx <= 28 THEN
        "Valves_DB".AftTblState[#j] := "Valves_DB".StateCode[#idx];
        "Valves_DB".AftTblNo[#j] := #idx;
        // RIGHT() strips the leading sign-space INT_TO_STRING puts in front of a positive
        // number: without it CONCAT yields 'CM- 29' rather than 'CM-29'.
        IF #idx < 10 THEN
            "Valves_DB".AftTblTag[#j] := CONCAT(IN1 := 'CM-0', IN2 := RIGHT(IN := INT_TO_STRING(#idx), L := 1));
        ELSE
            "Valves_DB".AftTblTag[#j] := CONCAT(IN1 := 'CM-', IN2 := RIGHT(IN := INT_TO_STRING(#idx), L := 2));
        END_IF;
        "Valve_Meta_DB".AftTblName[#j] := "Valve_Meta_DB".Name[#idx];
        "Valve_Meta_DB".AftTblLoc[#j] := "Valve_Meta_DB".Location[#idx];
        "Valve_Meta_DB".AftTblCmNo[#j] := "Valve_Meta_DB".CmNo[#idx];
        "Valve_Meta_DB".AftTblVTag[#j] := "Valve_Meta_DB".VTag[#idx];
        CASE "Valves_DB".StateCode[#idx] OF
            0: "Valves_DB".AftTblStateTxt[#j] := 'UNCONFIGURED';
            1: "Valves_DB".AftTblStateTxt[#j] := 'FAULT';
            2: "Valves_DB".AftTblStateTxt[#j] := 'LOCAL';
            3: "Valves_DB".AftTblStateTxt[#j] := 'OPEN';
            4: "Valves_DB".AftTblStateTxt[#j] := 'CLOSED';
            ELSE "Valves_DB".AftTblStateTxt[#j] := 'MOVING';
        END_CASE;
    ELSE
        "Valves_DB".AftTblState[#j] := 6;
        "Valves_DB".AftTblNo[#j] := 0;
        "Valves_DB".AftTblTag[#j] := '';
        "Valves_DB".AftTblStateTxt[#j] := '';
        "Valve_Meta_DB".AftTblName[#j] := '';
        "Valve_Meta_DB".AftTblLoc[#j] := '';
        "Valve_Meta_DB".AftTblCmNo[#j] := '';
        "Valve_Meta_DB".AftTblVTag[#j] := '';
    END_IF;
END_FOR;

// BILGE / ER: valves 29..56 (2 pages)
#base := 29 + "Valves_DB".ErPage * 14;
FOR #j := 1 TO 14 DO
    #idx := #base + #j - 1;
    IF #idx <= 56 THEN
        "Valves_DB".ErTblState[#j] := "Valves_DB".StateCode[#idx];
        "Valves_DB".ErTblNo[#j] := #idx - 28;
        "Valves_DB".ErTblTag[#j] := CONCAT(IN1 := 'CM-', IN2 := RIGHT(IN := INT_TO_STRING(#idx), L := 2));
        "Valve_Meta_DB".ErTblName[#j] := "Valve_Meta_DB".Name[#idx];
        "Valve_Meta_DB".ErTblLoc[#j] := "Valve_Meta_DB".Location[#idx];
        "Valve_Meta_DB".ErTblCmNo[#j] := "Valve_Meta_DB".CmNo[#idx];
        "Valve_Meta_DB".ErTblVTag[#j] := "Valve_Meta_DB".VTag[#idx];
        CASE "Valves_DB".StateCode[#idx] OF
            0: "Valves_DB".ErTblStateTxt[#j] := 'UNCONFIGURED';
            1: "Valves_DB".ErTblStateTxt[#j] := 'FAULT';
            2: "Valves_DB".ErTblStateTxt[#j] := 'LOCAL';
            3: "Valves_DB".ErTblStateTxt[#j] := 'OPEN';
            4: "Valves_DB".ErTblStateTxt[#j] := 'CLOSED';
            ELSE "Valves_DB".ErTblStateTxt[#j] := 'MOVING';
        END_CASE;
    ELSE
        "Valves_DB".ErTblState[#j] := 6;
        "Valves_DB".ErTblNo[#j] := 0;
        "Valves_DB".ErTblTag[#j] := '';
        "Valves_DB".ErTblStateTxt[#j] := '';
        "Valve_Meta_DB".ErTblName[#j] := '';
        "Valve_Meta_DB".ErTblLoc[#j] := '';
        "Valve_Meta_DB".ErTblCmNo[#j] := '';
        "Valve_Meta_DB".ErTblVTag[#j] := '';
    END_IF;
END_FOR;

// FORWARD BALLAST: valves 57..88 (3 pages: 14/14/4)
#base := 57 + "Valves_DB".FwdPage * 14;
FOR #j := 1 TO 14 DO
    #idx := #base + #j - 1;
    IF #idx <= 88 THEN
        "Valves_DB".FwdTblState[#j] := "Valves_DB".StateCode[#idx];
        "Valves_DB".FwdTblNo[#j] := #idx - 56;
        "Valves_DB".FwdTblTag[#j] := CONCAT(IN1 := 'CM-', IN2 := RIGHT(IN := INT_TO_STRING(#idx), L := 2));
        "Valve_Meta_DB".FwdTblName[#j] := "Valve_Meta_DB".Name[#idx];
        "Valve_Meta_DB".FwdTblLoc[#j] := "Valve_Meta_DB".Location[#idx];
        "Valve_Meta_DB".FwdTblCmNo[#j] := "Valve_Meta_DB".CmNo[#idx];
        "Valve_Meta_DB".FwdTblVTag[#j] := "Valve_Meta_DB".VTag[#idx];
        CASE "Valves_DB".StateCode[#idx] OF
            0: "Valves_DB".FwdTblStateTxt[#j] := 'UNCONFIGURED';
            1: "Valves_DB".FwdTblStateTxt[#j] := 'FAULT';
            2: "Valves_DB".FwdTblStateTxt[#j] := 'LOCAL';
            3: "Valves_DB".FwdTblStateTxt[#j] := 'OPEN';
            4: "Valves_DB".FwdTblStateTxt[#j] := 'CLOSED';
            ELSE "Valves_DB".FwdTblStateTxt[#j] := 'MOVING';
        END_CASE;
    ELSE
        "Valves_DB".FwdTblState[#j] := 6;
        "Valves_DB".FwdTblNo[#j] := 0;
        "Valves_DB".FwdTblTag[#j] := '';
        "Valves_DB".FwdTblStateTxt[#j] := '';
        "Valve_Meta_DB".FwdTblName[#j] := '';
        "Valve_Meta_DB".FwdTblLoc[#j] := '';
        "Valve_Meta_DB".FwdTblCmNo[#j] := '';
        "Valve_Meta_DB".FwdTblVTag[#j] := '';
    END_IF;
END_FOR;

// CONFIGURATION SCREEN: all 88 valves in one global sequence (6 pages of 16), not zone-scoped
// like the three windows above - this screen shows the whole fleet, so #idx IS the absolute
// valve number directly, no zone-start offset needed.
#base := 1 + "Valves_DB".CfgPage * 16;
FOR #j := 1 TO 16 DO
    #idx := #base + #j - 1;
    IF #idx <= 88 THEN
        "Valves_DB".CfgTblNo[#j] := #idx;
        IF #idx < 10 THEN
            "Valves_DB".CfgTblTag[#j] := CONCAT(IN1 := 'CM-0', IN2 := RIGHT(IN := INT_TO_STRING(#idx), L := 1));
        ELSE
            "Valves_DB".CfgTblTag[#j] := CONCAT(IN1 := 'CM-', IN2 := RIGHT(IN := INT_TO_STRING(#idx), L := 2));
        END_IF;
        IF #idx <= 28 THEN
            "Valves_DB".CfgTblZone[#j] := 'AFT BALLAST';
        ELSIF #idx <= 56 THEN
            "Valves_DB".CfgTblZone[#j] := 'BILGE-ER';
        ELSE
            "Valves_DB".CfgTblZone[#j] := 'BALLAST FWD';
        END_IF;
        "Valve_Meta_DB".CfgTblName[#j] := "Valve_Meta_DB".Name[#idx];
        "Valve_Meta_DB".CfgTblLoc[#j] := "Valve_Meta_DB".Location[#idx];
        // Client-schedule identity columns. Displayed verbatim - no fallback to the
        // computed CmNo/zone strings above, because a blank here is meaningful: it means
        // that valve has not been entered from the confirmed schedule yet, and showing a
        // derived 'CM-07' in its place would misrepresent unentered data as real.
        "Valve_Meta_DB".CfgTblCmNo[#j] := "Valve_Meta_DB".CmNo[#idx];
        "Valve_Meta_DB".CfgTblVTag[#j] := "Valve_Meta_DB".VTag[#idx];
        "Valve_Meta_DB".CfgTblSys[#j] := "Valve_Meta_DB".SysName[#idx];
        "Valve_Meta_DB".CfgTblFunc[#j] := "Valve_Meta_DB".FuncName[#idx];
        "Valves_DB".CfgTblConfigured[#j] := "Valves_DB".Valve[#idx].Configured;
        "Valves_DB".CfgTblState[#j] := "Valves_DB".StateCode[#idx];
        CASE "Valves_DB".StateCode[#idx] OF
            0: "Valves_DB".CfgTblStateTxt[#j] := 'UNCONFIGURED';
            1: "Valves_DB".CfgTblStateTxt[#j] := 'FAULT';
            2: "Valves_DB".CfgTblStateTxt[#j] := 'LOCAL';
            3: "Valves_DB".CfgTblStateTxt[#j] := 'OPEN';
            4: "Valves_DB".CfgTblStateTxt[#j] := 'CLOSED';
            ELSE "Valves_DB".CfgTblStateTxt[#j] := 'MOVING';
        END_CASE;
    ELSE
        "Valves_DB".CfgTblNo[#j] := 0;
        "Valves_DB".CfgTblTag[#j] := '';
        "Valves_DB".CfgTblZone[#j] := '';
        "Valve_Meta_DB".CfgTblName[#j] := '';
        "Valve_Meta_DB".CfgTblLoc[#j] := '';
        "Valve_Meta_DB".CfgTblCmNo[#j] := '';
        "Valve_Meta_DB".CfgTblVTag[#j] := '';
        "Valve_Meta_DB".CfgTblSys[#j] := '';
        "Valve_Meta_DB".CfgTblFunc[#j] := '';
        "Valves_DB".CfgTblConfigured[#j] := FALSE;
        "Valves_DB".CfgTblState[#j] := 6;
        "Valves_DB".CfgTblStateTxt[#j] := '';
    END_IF;
END_FOR;
